from pathlib import Path
import base64, html, json
ROOT=Path(__file__).resolve().parent
ideas=json.loads((ROOT/'concepts.json').read_text())
def data(path):
 return 'data:image/svg+xml;base64,'+base64.b64encode(path.read_bytes()).decode()
assets={i['id']:{n:data(ROOT/i['id']/(n+'.svg')) for n in ['icon','favicon','mark','mark-dark']} for i in ideas}
def image(id,kind,cls='',size=32,alt=''):
 return f'<img src="{assets[id][kind]}" class="{cls}" width="{size}" height="{size}" alt="{html.escape(alt)}">'
cards=[]
for n,i in enumerate(ideas):
 id=i['id'];sizes=''.join('<div>'+image(id,'favicon',size=s,alt=f"{i['name']} {s} 像素标签页图标")+f'<span>{s} px</span></div>' for s in [16,24,32,48])
 cards.append(f'''<article class="scheme"><div class="scheme-top"><span class="index">0{n+1}</span><h2>{i['name']}</h2><span class="english">{i['en']}</span></div><p class="meaning">{i['meaning']}</p>
 <div class="symbol-stage">{image(id,'icon','large-icon',128,i['name']+' 应用图标')}</div>
 <p class="context-label">网页页眉</p><div class="mini-header">{image(id,'mark','mini-mark',32,i['name']+' 页眉标记')}<div><strong>Free Bites at Vandy</strong><span>May the fork be with you.</span></div></div>
 <p class="context-label">浏览器标签页，16 px</p><div class="tab-strip"><div class="tab">{image(id,'favicon',size=16,alt=i['name']+' 实际 16 像素标签页图标')}<span>Free Bites at Vandy</span><span class="close" aria-hidden="true">×</span></div></div>
 <p class="context-label">小尺寸检查</p><div class="size-row">{sizes}</div>
 <div class="assessment"><p><span>特点</span>{i['strength']}</p><p><span>取舍</span>{i['tradeoff']}</p></div>
 <button class="try-button" type="button" data-concept="{id}" aria-pressed="{str(n==0).lower()}">查看网页示意<span aria-hidden="true">↗</span></button></article>''')
buttons=''.join(f'<button type="button" class="choice" data-concept="{i["id"]}" aria-pressed="{str(n==0).lower()}">{i["name"]}</button>' for n,i in enumerate(ideas))
downloads=''.join(f'<a href="{assets[i["id"]][kind]}" download="free-bites-{i["id"]}-{kind}.svg">{i["name"]} {label}</a>' for i in ideas for kind,label in [('mark','独立标记'),('icon','图标'),('favicon','标签页图标')])
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Free Bites 标识方向草案</title><link rel="icon" type="image/svg+xml" href="@@FAV@@"><style>
:root{font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:#242521;background:#f6f3ec;font-synthesis:none;--gold:#cfae70;--line:#e5e0d6}*{box-sizing:border-box}body{margin:0}main{max-width:1440px;margin:auto;padding:36px 30px 48px}.page-header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;padding-bottom:24px;border-bottom:1px solid var(--line);margin-bottom:24px}.eyebrow{font-size:11px;color:#817558;letter-spacing:.1em;margin:0 0 9px}h1{font-size:28px;line-height:1.3;letter-spacing:-.035em;font-weight:650;margin:0}.intro{font-size:13px;line-height:1.8;max-width:540px;color:#706f65;margin:8px 0 0}.phase{font-size:11px;color:#817558;border:1px solid #d8cdb7;border-radius:5px;padding:7px 10px;white-space:nowrap;margin-top:5px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.scheme{min-width:0;background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px}.scheme-top{display:grid;grid-template-columns:24px minmax(0,1fr);gap:3px 8px;align-items:center}.index{font-size:11px;color:#a38c5a;font-variant-numeric:tabular-nums}h2{font-size:18px;font-weight:650;letter-spacing:-.025em;margin:0}.english{grid-column:2;font-size:11px;color:#929083;margin-top:3px}.meaning{font-size:12px;line-height:1.7;color:#706f65;margin:16px 0 0;min-height:62px}.symbol-stage{display:flex;align-items:center;justify-content:center;min-height:178px;border-bottom:1px solid #efece5;margin-bottom:16px}.large-icon{display:block;width:128px;height:128px}.context-label{font-size:10px;letter-spacing:.03em;color:#929083;margin:16px 0 10px}.mini-header{display:flex;align-items:center;gap:9px;min-height:50px}.mini-mark{flex:none}.mini-header div{min-width:0}.mini-header strong{display:block;font-size:14px;line-height:1.5;letter-spacing:-.025em;font-weight:650}.mini-header div span{display:block;font-size:10px;color:#888678;font-style:italic;line-height:1.6}.tab-strip{padding:7px 7px 0;border-radius:7px;background:#f1f0ec;border:1px solid #e9e6df}.tab{display:flex;align-items:center;gap:7px;font-size:10px;background:#fff;border-radius:5px 5px 0 0;padding:9px 7px}.tab img{flex:none}.tab .close{margin-left:auto;font-size:14px;color:#999}.size-row{display:flex;justify-content:space-between;align-items:flex-end;gap:14px;height:76px;padding:4px 2px 8px}.size-row div{display:flex;flex-direction:column;align-items:center;gap:9px}.size-row span{font-size:10px;color:#929083;white-space:nowrap}.assessment{border-top:1px solid #efece5;padding-top:12px;margin:10px 0 16px;min-height:94px}.assessment p{font-size:11px;line-height:1.7;color:#706f65;margin:0 0 8px}.assessment p>span{display:inline-block;color:#242521;font-weight:600;margin-right:7px}button{font:inherit;cursor:pointer;border:1px solid #dad7cf;min-height:44px;background:#fff;color:#242521;border-radius:7px;font-size:12px;padding:10px 14px}button[aria-pressed=true]{background:#242521;color:#f6f3ec;border-color:#242521}.try-button{display:flex;width:100%;justify-content:space-between;align-items:center}.try-button[aria-pressed=true]{background:#fbf7ed;border-color:#cfae70;color:#655025}button:focus-visible,a:focus-visible{outline:3px solid #857044;outline-offset:4px}.review-note{font-size:12px;line-height:1.8;color:#706f65;margin:20px 0 32px}.application{border-top:1px solid var(--line);padding-top:24px}.application-intro{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:18px}.application-intro h2{font-size:19px}.application-intro p{font-size:12px;color:#706f65;margin:6px 0 0}.theme-switch{display:flex;gap:8px}.theme-switch button{min-height:38px;font-size:11px;padding:8px 14px}.choices{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}.example{background:#fff;border:1px solid var(--line);border-radius:12px;padding:28px 32px;color:#242521;--demo-muted:#8c8b80;--demo-rule:#eeece5}.example[data-theme=dark]{background:#242521;color:#f6f3ec;--demo-muted:#aaa698;--demo-rule:#45463f}.example-header{display:flex;align-items:center;justify-content:space-between;gap:30px}.example-brand{display:grid;grid-template-columns:44px minmax(0,1fr);align-items:center;gap:14px}.example-brand img{width:44px;height:44px}.example-title{font-size:26px;font-weight:650;letter-spacing:-.035em;line-height:1.25;margin:0}.example-brand .slogan{font-size:13px;font-style:italic;color:var(--demo-muted);margin:5px 0 0}.sample-label{font-size:10px;color:var(--demo-muted);white-space:nowrap}.demo-toolbar{display:flex;align-items:center;gap:24px;font-size:12px;padding:24px 0 20px;border-bottom:1px solid var(--demo-rule);color:var(--demo-muted)}.demo-toolbar span:first-child{color:inherit;font-weight:600}.demo-sub{font-size:12px;line-height:1.8;margin:20px 0;color:var(--demo-muted)}.mock-events{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}.mock-event{border-top:1px solid var(--demo-rule);padding:16px 0 0}.mock-event h3{font-size:15px;font-weight:600;margin:0 0 7px}.mock-event p{font-size:12px;color:var(--demo-muted);margin:0 0 7px}.mock-event .tag{font-size:10px;border:1px solid var(--demo-rule);display:inline-block;border-radius:4px;padding:3px 6px;color:var(--demo-muted)}.interpretation{font-size:12px;line-height:1.8;color:#706f65;max-width:760px;margin:20px 0 0}footer{font-size:11px;line-height:1.8;color:#929083;border-top:1px solid var(--line);padding-top:22px;margin-top:30px}.downloads{display:flex;gap:8px 18px;flex-wrap:wrap;margin:12px 0}a{color:#796138;text-decoration:underline;text-underline-offset:3px;font-size:11px}.baseline{display:flex;align-items:center;gap:10px;margin-top:18px}.baseline img{width:28px;height:28px}.baseline span{font-size:11px;color:#929083}
@media(max-width:1120px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.meaning{min-height:42px}.assessment{min-height:76px}.scheme{padding:22px}.size-row{justify-content:flex-start;gap:28px}.mini-header strong{font-size:16px}.mini-header div span{font-size:11px}}@media(max-width:650px){main{padding:24px 16px 32px}.page-header{flex-direction:column;gap:12px}.phase{margin:0}h1{font-size:25px}.grid{gap:12px}.scheme{padding:14px}h2{font-size:16px}.meaning{min-height:82px}.large-icon{width:112px;height:112px}.symbol-stage{min-height:150px}.mini-header strong{font-size:12px}.mini-header div span{font-size:9px}.mini-header{gap:6px}.size-row{gap:14px;justify-content:space-between}.assessment{min-height:114px}.application-intro{align-items:flex-start;flex-direction:column;gap:12px}.example{padding:22px 18px}.example-header{align-items:flex-start;flex-direction:column;gap:14px}.example-title{font-size:24px}.example-brand{gap:10px}.mock-events{grid-template-columns:minmax(0,1fr);gap:20px}}@media(max-width:420px){.grid{grid-template-columns:minmax(0,1fr)}.scheme{padding:20px}.meaning{min-height:0}.symbol-stage{min-height:160px}.mini-header strong{font-size:16px}.mini-header div span{font-size:11px}.size-row{justify-content:flex-start;gap:28px}.assessment{min-height:0}.choice{flex:1 1 40%}.example-title{font-size:21px}}
</style></head><body><main>
<header class="page-header"><div><p class="eyebrow">FREE BITES AT VANDY</p><h1>四种更自然的标识方向</h1><p class="intro">用食物、咬痕、信号与位置建立识别度。四个草案沿用黑金配色，并在相同页眉、标签页与小尺寸环境中展示。</p></div><span class="phase">方向草案 / 01</span></header>
<div class="grid">@@CARDS@@</div>
<p class="review-note">我的初步判断：餐盘与餐叉的含义最稳妥；一口好味与 Free Bites 的名称联系更紧密，也更容易形成独立的品牌记忆。</p>
<section class="application" aria-labelledby="application-title"><div class="application-intro"><div><h2 id="application-title">在紧凑页眉中查看</h2><p>切换方案，观察标识与标题、正文之间的关系。</p></div><div class="theme-switch" role="group" aria-label="网页示意背景"><button type="button" data-theme="light" aria-pressed="true">浅色</button><button type="button" data-theme="dark" aria-pressed="false">深色</button></div></div><div class="choices" role="group" aria-label="网页示意方案">@@CHOICES@@</div>
<div class="example" id="example" data-theme="light"><header class="example-header"><div class="example-brand"><img id="example-mark" src="@@MARK@@" width="44" height="44" alt="餐盘与餐叉标识"><div><p class="example-title">Free Bites at Vandy</p><p class="slogan">May the fork be with you.</p></div></div><span class="sample-label">版式示意，非实时活动</span></header><div class="demo-toolbar" aria-hidden="true"><span>Today</span><span>Week</span><span>Map</span></div><p class="demo-sub">探索校园中的餐点与活动，查看时间、地点和参与条件。</p><div class="mock-events"><article class="mock-event"><h3>Campus lunch gathering</h3><p>12:00 PM / Student Center</p><span class="tag">Lunch</span></article><article class="mock-event"><h3>Coffee and conversation</h3><p>3:00 PM / Campus Lounge</p><span class="tag">Light refreshments</span></article></div></div>
<p class="interpretation" id="interpretation" aria-live="polite">当前展示：餐盘与餐叉。用餐叉和餐盘组成日常用餐的记号，侧重食物本身。</p></section>
<footer>本页内嵌四个草案的 SVG，可离线打开。标签页按实际像素显示；细节在专用小尺寸版本中简化。<div class="downloads">@@DOWNLOADS@@</div><div class="baseline">@@BASELINE@@<span>现有 Codex 原版保留作为参考。</span><a href="../comparison-five.html">查看此前的比较页</a></div></footer>
</main><script>
const assets=@@ASSETS@@;const concepts=@@CONCEPTS@@;let current='table';let theme='light';
function update(){const i=concepts.find(i=>i.id===current);document.querySelector('#example-mark').src=assets[current][theme==='dark'?'mark-dark':'mark'];document.querySelector('#example-mark').alt=i.name+'标识';document.querySelector('#interpretation').textContent='当前展示：'+i.name+'。'+i.meaning;document.querySelectorAll('button[data-concept]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.concept===current)));document.querySelectorAll('button[data-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===theme)));document.querySelector('#example').dataset.theme=theme;}
document.querySelectorAll('button[data-concept]').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.concept;update();if(b.classList.contains('try-button'))document.querySelector('#application-title').scrollIntoView({block:'start',behavior:'instant'});}));document.querySelectorAll('button[data-theme]').forEach(b=>b.addEventListener('click',()=>{theme=b.dataset.theme;update();}));
</script></body></html>'''
replacements={'CARDS':''.join(cards),'CHOICES':buttons,'MARK':assets['table']['mark'],'FAV':assets['table']['favicon'],'DOWNLOADS':downloads,'BASELINE':'<img src="'+data(ROOT.parent/'vfr-icon.svg')+'" width="28" height="28" alt="现有 Codex 原版图标">','ASSETS':json.dumps(assets),'CONCEPTS':json.dumps(ideas,ensure_ascii=False)}
for k,v in replacements.items():page=page.replace('@@'+k+'@@',v)
assert '@@' not in page
(ROOT/'preview.html').write_text(page)
print('Created standalone interactive preview.')
